  "official/c54351224.lua":"--リチュアル・ウェポン\n--Ritual Weapon\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\taux.AddEquipProcedure(c,nil,s.filter)\n\t--atk up\n\tlocal e2=Effect.CreateEffect(c)\n\te2:SetType(EFFECT_TYPE_EQUIP)\n\te2:SetCode(EFFECT_UPDATE_ATTACK)\n\te2:SetValue(1500)\n\tc:RegisterEffect(e2)\n\t--def up\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetType(EFFECT_TYPE_EQUIP)\n\te3:SetCode(EFFECT_UPDATE_DEFENSE)\n\te3:SetValue(1500)\n\tc:RegisterEffect(e3)\nend\nfunction s.filter(c)\n\treturn c:IsType(TYPE_RITUAL) and c:IsLevelBelow(6)\nend",
  "c54351224.lua":"--リチュアル・ウェポン\n--Ritual Weapon\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\taux.AddEquipProcedure(c,nil,s.filter)\n\t--atk up\n\tlocal e2=Effect.CreateEffect(c)\n\te2:SetType(EFFECT_TYPE_EQUIP)\n\te2:SetCode(EFFECT_UPDATE_ATTACK)\n\te2:SetValue(1500)\n\tc:RegisterEffect(e2)\n\t--def up\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetType(EFFECT_TYPE_EQUIP)\n\te3:SetCode(EFFECT_UPDATE_DEFENSE)\n\te3:SetValue(1500)\n\tc:RegisterEffect(e3)\nend\nfunction s.filter(c)\n\treturn c:IsType(TYPE_RITUAL) and c:IsLevelBelow(6)\nend",
  "official/c54415063.lua":"--ハーピィ・レディ3\n--Harpie Lady 3\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--atk limit\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_CONTINUOUS)\n\te1:SetCode(EVENT_BATTLED)\n\te1:SetRange(LOCATION_MZONE)\n\te1:SetOperation(s.operation)\n\tc:RegisterEffect(e1)\nend\ns.listed_names={CARD_HARPIE_LADY}\nfunction s.operation(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tlocal bc=c:GetBattleTarget()\n\tif not bc then return end\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_SINGLE)\n\te1:SetCode(EFFECT_CANNOT_ATTACK_ANNOUNCE)\n\te1:SetReset(RESETS_STANDARD_PHASE_END|RESET_SELF_TURN,2)\n\tbc:RegisterEffect(e1)\nend",
  "c54415063.lua":"--ハーピィ・レディ3\n--Harpie Lady 3\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--atk limit\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_CONTINUOUS)\n\te1:SetCode(EVENT_BATTLED)\n\te1:SetRange(LOCATION_MZONE)\n\te1:SetOperation(s.operation)\n\tc:RegisterEffect(e1)\nend\ns.listed_names={CARD_HARPIE_LADY}\nfunction s.operation(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tlocal bc=c:GetBattleTarget()\n\tif not bc then return end\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_SINGLE)\n\te1:SetCode(EFFECT_CANNOT_ATTACK_ANNOUNCE)\n\te1:SetReset(RESETS_STANDARD_PHASE_END|RESET_SELF_TURN,2)\n\tbc:RegisterEffect(e1)\nend",
