  "official/c54652250.lua":"--人喰い虫\n--Man-Eater Bug\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--flip\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetDescription(aux.Stringid(id,0))\n\te1:SetCategory(CATEGORY_DESTROY)\n\te1:SetProperty(EFFECT_FLAG_CARD_TARGET)\n\te1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_FLIP)\n\te1:SetTarget(s.target)\n\te1:SetOperation(s.operation)\n\tc:RegisterEffect(e1)\nend\nfunction s.target(e,tp,eg,ep,ev,re,r,rp,chk,chkc)\n\tif chkc then return chkc:IsLocation(LOCATION_MZONE) end\n\tif chk==0 then return true end\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_DESTROY)\n\tlocal g=Duel.SelectTarget(tp,aux.TRUE,tp,LOCATION_MZONE,LOCATION_MZONE,1,1,nil)\n\tDuel.SetOperationInfo(0,CATEGORY_DESTROY,g,#g,0,0)\nend\nfunction s.operation(e,tp,eg,ep,ev,re,r,rp)\n\tlocal tc=Duel.GetFirstTarget()\n\tif tc and tc:IsRelateToEffect(e) then\n\t\tDuel.Destroy(tc,REASON_EFFECT)\n\tend\nend",
  "c54652250.lua":"--人喰い虫\n--Man-Eater Bug\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--flip\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetDescription(aux.Stringid(id,0))\n\te1:SetCategory(CATEGORY_DESTROY)\n\te1:SetProperty(EFFECT_FLAG_CARD_TARGET)\n\te1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_FLIP)\n\te1:SetTarget(s.target)\n\te1:SetOperation(s.operation)\n\tc:RegisterEffect(e1)\nend\nfunction s.target(e,tp,eg,ep,ev,re,r,rp,chk,chkc)\n\tif chkc then return chkc:IsLocation(LOCATION_MZONE) end\n\tif chk==0 then return true end\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_DESTROY)\n\tlocal g=Duel.SelectTarget(tp,aux.TRUE,tp,LOCATION_MZONE,LOCATION_MZONE,1,1,nil)\n\tDuel.SetOperationInfo(0,CATEGORY_DESTROY,g,#g,0,0)\nend\nfunction s.operation(e,tp,eg,ep,ev,re,r,rp)\n\tlocal tc=Duel.GetFirstTarget()\n\tif tc and tc:IsRelateToEffect(e) then\n\t\tDuel.Destroy(tc,REASON_EFFECT)\n\tend\nend",
  "official/c54704216.lua":"--拷問車輪\n--Nightmare Wheel\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\taux.AddPersistentProcedure(c,1,nil,CATEGORY_DISABLE,nil,TIMING_STANDBY_PHASE,TIMINGS_CHECK_MONSTER,nil,nil,nil,nil,true)\n\t--eff\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_FIELD)\n\te1:SetCode(EFFECT_CANNOT_ATTACK)\n\te1:SetRange(LOCATION_SZONE)\n\te1:SetTargetRange(LOCATION_MZONE,LOCATION_MZONE)\n\te1:SetTarget(aux.PersistentTargetFilter)\n\tc:RegisterEffect(e1)\n\tlocal e2=e1:Clone()\n\te2:SetCode(EFFECT_CANNOT_CHANGE_POSITION)\n\te2:SetProperty(EFFECT_FLAG_SET_AVAILABLE)\n\tc:RegisterEffect(e2)\n\t--damage\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetDescription(aux.Stringid(id,0))\n\te3:SetType(EFFECT_TYPE_FIELD+EFFECT_TYPE_TRIGGER_F)\n\te3:SetCategory(CATEGORY_DAMAGE)\n\te3:SetCode(EVENT_PHASE|PHASE_STANDBY)\n\te3:SetRange(LOCATION_SZONE)\n\te3:SetCountLimit(1)\n\te3:SetCondition(s.damcon)\n\te3:SetTarget(s.damtg)\n\te3:SetOperation(s.damop)\n\tc:RegisterEffect(e3)\n\t--Destroy\n\tlocal e4=Effect.CreateEffect(c)\n\te4:SetType(EFFECT_TYPE_CONTINUOUS+EFFECT_TYPE_FIELD)\n\te4:SetRange(LOCATION_SZONE)\n\te4:SetCode(EVENT_LEAVE_FIELD)\n\te4:SetCondition(s.descon)\n\te4:SetOperation(s.desop)\n\tc:RegisterEffect(e4)\nend\nfunction s.descon(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tif c:IsStatus(STATUS_DESTROY_CONFIRMED) then return false end\n\tlocal tc=c:GetFirstCardTarget()\n\treturn tc and eg:IsContains(tc)\nend\nfunction s.desop(e,tp,eg,ep,ev,re,r,rp)\n\tDuel.Destroy(e:GetHandler(),REASON_EFFECT)\nend\nfunction s.damcon(e,tp,eg,ep,ev,re,r,rp)\n\treturn tp==Duel.GetTurnPlayer() and e:GetHandler():GetFirstCardTarget()~=nil\nend\nfunction s.damtg(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return true end\n\tDuel.SetTargetPlayer(1-tp)\n\tDuel.SetTargetParam(500)\n\tDuel.SetOperationInfo(0,CATEGORY_DAMAGE,nil,0,1-tp,500)\nend\nfunction s.damop(e,tp,eg,ep,ev,re,r,rp)\n\tif not e:GetHandler():IsRelateToEffect(e) then return end\n\tlocal p,d=Duel.GetChainInfo(0,CHAININFO_TARGET_PLAYER,CHAININFO_TARGET_PARAM)\n\tDuel.Damage(p,d,REASON_EFFECT)\nend",
  "c54704216.lua":"--拷問車輪\n--Nightmare Wheel\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\taux.AddPersistentProcedure(c,1,nil,CATEGORY_DISABLE,nil,TIMING_STANDBY_PHASE,TIMINGS_CHECK_MONSTER,nil,nil,nil,nil,true)\n\t--eff\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_FIELD)\n\te1:SetCode(EFFECT_CANNOT_ATTACK)\n\te1:SetRange(LOCATION_SZONE)\n\te1:SetTargetRange(LOCATION_MZONE,LOCATION_MZONE)\n\te1:SetTarget(aux.PersistentTargetFilter)\n\tc:RegisterEffect(e1)\n\tlocal e2=e1:Clone()\n\te2:SetCode(EFFECT_CANNOT_CHANGE_POSITION)\n\te2:SetProperty(EFFECT_FLAG_SET_AVAILABLE)\n\tc:RegisterEffect(e2)\n\t--damage\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetDescription(aux.Stringid(id,0))\n\te3:SetType(EFFECT_TYPE_FIELD+EFFECT_TYPE_TRIGGER_F)\n\te3:SetCategory(CATEGORY_DAMAGE)\n\te3:SetCode(EVENT_PHASE|PHASE_STANDBY)\n\te3:SetRange(LOCATION_SZONE)\n\te3:SetCountLimit(1)\n\te3:SetCondition(s.damcon)\n\te3:SetTarget(s.damtg)\n\te3:SetOperation(s.damop)\n\tc:RegisterEffect(e3)\n\t--Destroy\n\tlocal e4=Effect.CreateEffect(c)\n\te4:SetType(EFFECT_TYPE_CONTINUOUS+EFFECT_TYPE_FIELD)\n\te4:SetRange(LOCATION_SZONE)\n\te4:SetCode(EVENT_LEAVE_FIELD)\n\te4:SetCondition(s.descon)\n\te4:SetOperation(s.desop)\n\tc:RegisterEffect(e4)\nend\nfunction s.descon(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tif c:IsStatus(STATUS_DESTROY_CONFIRMED) then return false end\n\tlocal tc=c:GetFirstCardTarget()\n\treturn tc and eg:IsContains(tc)\nend\nfunction s.desop(e,tp,eg,ep,ev,re,r,rp)\n\tDuel.Destroy(e:GetHandler(),REASON_EFFECT)\nend\nfunction s.damcon(e,tp,eg,ep,ev,re,r,rp)\n\treturn tp==Duel.GetTurnPlayer() and e:GetHandler():GetFirstCardTarget()~=nil\nend\nfunction s.damtg(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return true end\n\tDuel.SetTargetPlayer(1-tp)\n\tDuel.SetTargetParam(500)\n\tDuel.SetOperationInfo(0,CATEGORY_DAMAGE,nil,0,1-tp,500)\nend\nfunction s.damop(e,tp,eg,ep,ev,re,r,rp)\n\tif not e:GetHandler():IsRelateToEffect(e) then return end\n\tlocal p,d=Duel.GetChainInfo(0,CHAININFO_TARGET_PLAYER,CHAININFO_TARGET_PARAM)\n\tDuel.Damage(p,d,REASON_EFFECT)\nend",
